// =============================================================
// Noellyne AI Brain v3.1 — Persistent Cloud Memory + Anti-Abuse Quotas + Actions
// =============================================================
const id = $('Resolve Identity & Intent').first().json;
const planMeta = $('Resolve Plan & Quota Keys').first().json;
const memRaw = $('Read User AI Memory').first().json || {};
const mem = Array.isArray(memRaw) ? (memRaw[0] || {}) : (memRaw.subject_key ? memRaw : {});
const quotaRaw = $('Consume Daily Quota RPC').first().json || {};

const question = id.question;
const history = id.history || [];
const matchCtx = id.matchCtx || '';
const userTier = planMeta.effectiveTier || 'guest';
const userPlan = planMeta.plan || 'guest';
const dailyLimit = planMeta.dailyLimit;
const memoryKey = planMeta.memoryKey || '';

const isUnlimited = dailyLimit < 0 || quotaRaw.unlimited === true;
const quotaAllowed = isUnlimited ? true : (quotaRaw.allowed !== false);
const quotaUsed = Number(quotaRaw.used ?? 0);
const quotaRemaining = isUnlimited ? -1 : Math.max(0, Number(quotaRaw.remaining ?? (dailyLimit - quotaUsed)));

const rateLimitObj = {
  tier: userTier,
  plan: userPlan,
  limit: isUnlimited ? -1 : dailyLimit,
  used: quotaUsed,
  remaining: quotaRemaining,
  unlimited: isUnlimited,
  period: 'day',
  resetsAt: '00:00 EAT'
};

// Build merged User Memory (existing cloud memory + app pinned teams + new turn signals)
const qLow = question.toLowerCase();
const existingTeams = Array.isArray(mem.favorite_teams) ? mem.favorite_teams : [];
const mergedTeams = [...new Set([...existingTeams, ...(id.profilePinned || [])])].slice(0, 12);
const knownTeams = ['Simba SC','Yanga','Azam FC','Arsenal','Liverpool','Man United','Man City','Chelsea','Real Madrid','Barcelona','Bayern','PSG','Juventus','AC Milan','Inter Milan','Lakers','Celtics','Warriors','Bucks','Nuggets','Suns','Mavericks'];
for (const tm of knownTeams) {
  if (qLow.includes(tm.toLowerCase().replace(' sc', '').replace(' fc', '')) && !mergedTeams.includes(tm)) {
    mergedTeams.push(tm);
  }
}
const finalTeams = mergedTeams.slice(0, 12);
const displayName = id.profileName || mem.display_name || (userTier === 'vip' ? 'Mwijay' : '');
const usualStake = id.stakeTzs || (Number(mem.usual_stake_tzs) || null);
let prefSport = mem.preferred_sport || '';
if (/(nba|basket|lakers|celtics|warriors|points)/i.test(qLow)) prefSport = prefSport === 'football' ? 'both' : 'basketball';
else if (/(football|mpira|premier|la liga|serie a|simba|yanga)/i.test(qLow)) prefSport = prefSport === 'basketball' ? 'both' : 'football';

const memoryPayload = (memoryKey && question.length >= 3)
  ? {
      subject_key: memoryKey,
      display_name: displayName,
      favorite_teams: finalTeams,
      usual_stake_tzs: usualStake,
      preferred_sport: prefSport,
      notes: question.slice(0, 180),
      updated_at: new Date().toISOString()
    }
  : null;

if (!question) {
  return [{
    json: {
      reply: 'Karibu Noellyne AI! Niulize kuhusu picks za Football, NBA, matokeo, Altraware Technology, au andika "Nina 20,000 leo" nikugawie mtaji.',
      provider: 'instant',
      model: 'router',
      tier: userTier,
      plan: userPlan,
      rateLimit: rateLimitObj,
      actions: [
        { type: 'open_picks', label: 'Daily Picks' },
        { type: 'open_results', label: 'Matokeo & ROI' }
      ]
    }
  }];
}

const rows = $input.all().map(i => i.json).filter(r => r && r.match && r.pick);
const published = rows.filter(r => r.status === 'published');
const settled = rows.filter(r => r.status === 'settled' && (r.result === 'won' || r.result === 'lost'));
const fbPub = published.filter(r => r.sport !== 'basketball');
const bbPub = published.filter(r => r.sport === 'basketball');

const wins = settled.filter(r => r.result === 'won').length;
const losses = settled.filter(r => r.result === 'lost').length;
const wr = settled.length ? ((wins / settled.length) * 100).toFixed(1) : '0.0';
const netUnits = settled.reduce((acc, r) => acc + (Number(r.profit_units) || 0), 0);
const UNIT_TZS = 1000;
const netTzs = Math.round(netUnits * UNIT_TZS);
const tzs = n => Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');

// Instant 0-cost Stake Split Calculator
if (id.wantsSlip) {
  const total = id.stakeTzs || usualStake || 10000;
  const s1 = Math.round(total * 0.40);
  const s2 = Math.round(total * 0.40);
  const s3 = total - s1 - s2;
  const topFb = fbPub.slice().sort((a, b) => (b.confidence || 0) - (a.confidence || 0))[0];
  const topBb = bbPub.slice().sort((a, b) => (b.confidence || 0) - (a.confidence || 0))[0];
  const fbOdds = topFb && topFb.odds > 1 ? Number(topFb.odds) : 1.40;
  const bbOdds = topBb && topBb.odds > 1 ? Number(topBb.odds) : 1.50;
  const dblOdds = +(fbOdds * bbOdds).toFixed(2);
  const fbLabel = topFb ? (topFb.match + ' → ' + topFb.pick + ' @ ' + fbOdds.toFixed(2)) : 'Top Football Anchor @ ' + fbOdds.toFixed(2);
  const bbLabel = topBb ? (topBb.match + ' → ' + topBb.pick + ' @ ' + bbOdds.toFixed(2)) : 'Top NBA Anchor @ ' + bbOdds.toFixed(2);
  const ret1 = Math.round(s1 * fbOdds);
  const ret2 = Math.round(s2 * bbOdds);
  const ret3 = Math.round(s3 * dblOdds);
  const reply = [
    'MGAWO WA MTAJI — TZS ' + tzs(total),
    '━━━━━━━━━━━━━━━━━━━━━━',
    'Ticket 1 (40% · Single Football Anchor):',
    '  ' + fbLabel,
    '  Weka TZS ' + tzs(s1) + ' → Malipo TZS ' + tzs(ret1),
    '',
    'Ticket 2 (40% · Single NBA Anchor):',
    '  ' + bbLabel,
    '  Weka TZS ' + tzs(s2) + ' → Malipo TZS ' + tzs(ret2),
    '',
    'Ticket 3 (20% · Safe Double @ ' + dblOdds + '):',
    '  Weka TZS ' + tzs(s3) + ' → Malipo TZS ' + tzs(ret3),
    '━━━━━━━━━━━━━━━━━━━━━━',
    'Zote zikitiki: TZS ' + tzs(ret1 + ret2 + ret3) + ' (Faida +TZS ' + tzs(ret1 + ret2 + ret3 - total) + ')',
    'Ulinzi: Single moja ikiteleza, nyingine inalinda mtaji wako!'
  ].join('\n');

  return [{
    json: {
      reply,
      provider: 'instant',
      model: 'stake-calculator',
      tier: userTier,
      plan: userPlan,
      rateLimit: rateLimitObj,
      livePicksCount: published.length,
      settledCount: settled.length,
      memoryPayload,
      actions: [
        { type: 'copy_text', label: 'Copy Mgawo', text: reply },
        { type: 'open_picks', label: 'Fungua Daily Picks' }
      ]
    }
  }];
}

// Enforce Daily Quota
if (!quotaAllowed) {
  if (userTier === 'guest') {
    const msg = [
      'Umetumia maswali yako 3 ya bure ya AI leo kama mgeni.',
      '',
      'Ingia na akaunti yako ya Google BURE sasa hivi upate:',
      '- Maswali 10 ya Noellyne AI kila siku',
      '- AI inayokumbuka timu na mipangilio yako',
      '',
      'Pia bado unaweza kutumia Daily Picks, Results/ROI na Mgawo wa Mtaji ("Nina 20,000 leo") bila kikomo!'
    ].join('\n');
    return [{
      json: {
        reply: msg,
        quotaReached: true,
        provider: 'quota-guard',
        model: 'daily-limit',
        tier: userTier,
        plan: userPlan,
        rateLimit: rateLimitObj,
        actions: [
          { type: 'sign_in', label: 'Ingia na Google (10/siku)' },
          { type: 'open_picks', label: 'Daily Picks' }
        ]
      }
    }];
  }

  const msg = [
    `Umetumia maswali yako ${dailyLimit}/${dailyLimit} ya Noellyne AI kwa leo (yanarejea saa 00:00 usiku EAT).`,
    '',
    'Unahitaji maswali zaidi ya uchambuzi kila siku? Wasiliana na Altraware Technology kwa Noellyne Pro Access!',
    'Kwa sasa bado unaweza kuona Daily Picks zote, Matokeo/ROI na kugawa mtaji ("Nina 20,000 leo") bure.'
  ].join('\n');
  return [{
    json: {
      reply: msg,
      quotaReached: true,
      provider: 'quota-guard',
      model: 'daily-limit',
      tier: userTier,
      plan: userPlan,
      rateLimit: rateLimitObj,
      actions: [
        { type: 'open_url', label: 'Omba Noellyne Pro (WhatsApp)', url: 'https://wa.me/255620641695?text=Habari%20Altraware%2C%20nahitaji%20Noellyne%20Pro%20Access' },
        { type: 'open_picks', label: 'Daily Picks' }
      ]
    }
  }];
}

// Smart Contextual Actions
const actions = [];
const matchedStreamPick = published.find(p => {
  if (!p.stream_id) return false;
  const words = String(p.match || '').toLowerCase().split(/\s+vs\s+|\s+@\s+|\s+/).filter(w => w.length >= 4);
  return words.some(w => qLow.includes(w));
});
if (matchedStreamPick) {
  actions.push({ type: 'open_watch', label: 'Watch ' + matchedStreamPick.match.split(' vs ')[0], streamId: matchedStreamPick.stream_id });
}
const asksAltraware = /(altraware|mwijay|david|clemence|faida|caretrack|quickopia|motion lab|uaut|tanzaniareach|aymi|who made|nani katengeneza|nani aliunda|website|tovuti|app|wasiliana|contact|namba|bei|pro|lipia)/i.test(qLow);
if (asksAltraware) {
  actions.push({ type: 'open_url', label: 'Tembelea Altraware', url: 'https://altra.tanzaniareach.com/' });
  actions.push({ type: 'open_url', label: 'WhatsApp Mwijay', url: 'https://wa.me/255620641695?text=Habari%20Mwijay%20kutoka%20Noellyne%20App' });
}
if (/(matokeo|results|rekodi|roi|jana|faida|ushindi|won|lost)/i.test(qLow)) {
  actions.push({ type: 'open_results', label: 'Angalia Matokeo & ROI' });
} else if (/(pick|mechi|leo|football|nba|basket|bet|odds|mkeka|shinda|chambua)/i.test(qLow)) {
  actions.push({ type: 'open_picks', label: 'Fungua Daily Picks' });
}
if (userTier === 'guest' && quotaRemaining <= 1) {
  actions.push({ type: 'sign_in', label: 'Ingia na Google (10/siku)' });
}
const seenAct = new Set();
const finalActions = actions.filter(a => {
  const k = a.type + ':' + a.label;
  if (seenAct.has(k)) return false;
  seenAct.add(k);
  return true;
}).slice(0, 3);

const fmtPick = p => {
  const inj = p.injury_note ? (' | Injury: ' + p.injury_note) : '';
  return '- [' + (p.sport === 'basketball' ? 'NBA' : p.league) + '] ' + p.match + ' | Pick: ' + p.pick + ' @ ' + p.odds + ' | Conf: ' + p.confidence + '% | Edge: +' + p.edge_pct + '% | Tier: ' + (p.tier || 'STRONG') + ' | Dau: ' + (p.units || 2) + 'u' + inj + (p.reasoning ? (' | Info: ' + p.reasoning.slice(0, 140)) : '');
};

const picksContext = [
  'FOOTBALL PICKS LIVE (' + fbPub.length + '):',
  fbPub.length ? fbPub.slice(0, 8).map(fmtPick).join('\n') : 'Hakuna football picks live sasa.',
  '',
  'NBA BASKETBALL PICKS LIVE (' + bbPub.length + '):',
  bbPub.length ? bbPub.slice(0, 8).map(fmtPick).join('\n') : 'Hakuna NBA picks live sasa.',
  '',
  'REKODI YA MATOKEO YALIYOKAMILIKA (Supabase Live):',
  settled.length
    ? (wins + 'W / ' + losses + 'L (' + wr + '% Win Rate) | Net: ' + (netUnits >= 0 ? '+' : '') + netUnits.toFixed(2) + 'u (' + (netTzs >= 0 ? '+TZS ' : '-TZS ') + tzs(Math.abs(netTzs)) + ')\n' +
       settled.slice(-8).reverse().map(r => '  - ' + (r.result === 'won' ? 'WON' : 'LOST') + ': ' + r.match + ' (' + (r.score || '-') + ') -> ' + r.pick + ' @ ' + r.odds).join('\n'))
    : 'Bado hakuna matokeo yaliyofungwa.'
].join('\n');

const userMemoryCtx = [
  'KUMBUKUMBU YA MTUMIAJI (CLOUD MEMORY):',
  displayName ? ('- Jina: ' + displayName) : '',
  finalTeams.length ? ('- Timu anazopenda: ' + finalTeams.join(', ')) : '',
  usualStake ? ('- Mtaji wa kawaida: TZS ' + tzs(usualStake)) : '',
  prefSport ? ('- Mchezo anaoupenda: ' + prefSport) : '',
  mem.notes ? ('- Mada ya mwisho aliyouliza: ' + mem.notes) : ''
].filter(Boolean).join('\n');

const ALTRAWARE_PROFILE = [
  'KUHUSU ALTRAWARE TECHNOLOGY LTD & MWASISI (MWIJAY):',
  '- App ya Noellyne imeundwa na Altraware Technology Ltd (Dar es Salaam, Tanzania) — kaulimbiu: "Rooted at Home. Engineered for the World."',
  '- Co-Founders: David Erick Mwijage (maarufu mtandaoni kama Mwijay Davie — Engineering, Systems Architecture & AI Automation) na Clemence W. N\'gunda (Product & Business Operations).',
  '- Bidhaa nyingine za Altraware: Faida POS (offline-first retail POS na M-Pesa/Tigo Pesa/Airtel Money), CareTrack (kliniki), TanzaniaReach (tanzaniareach.com), UAUTConnect (uautconnect.com), AYMI Africa (aymiafrica.org), Altraware Motion Lab (altra-motion-lab.vercel.app), Quickopia (quickopia-web.vercel.app).',
  '- Mawasiliano ya biashara: Website https://altra.tanzaniareach.com/ | Email: altrawaretechnology@gmail.com | WhatsApp/Simu: +255 620 641 695 au +255 792 867 427.',
  '- SHERIA: Usiwahi kutaja majina ya zamani yaliyostaafu (Piano Sifa, Ideazzy) wala LIMS.'
].join('\n');

const SYS = [
  'Wewe ni Noellyne AI — msaidizi mahiri wa uchambuzi wa michezo (Football & NBA analytics) na mwakilishi rasmi wa Altraware Technology Ltd ndani ya app ya Noellyne.',
  userTier === 'vip' ? 'Mtumiaji huyu ni David Erick Mwijage (Mwijay — Founder & VIP Owner) — mpe uchambuzi wa kina zaidi, wa haraka na wa moja kwa moja.' : '',
  'Jibu kwa Kiswahili safi (au Kiingereza ikiwa mtumiaji ameuliza kwa Kiingereza), kifupi na chenye thamani (mistari 4-10), BILA Markdown (** au *) na BILA HTML tags.',
  'Tumia KUMBUKUMBU YA MTUMIAJI (kama zipo) kufanya mazungumzo yawe binafsi na yanayokumbuka mambo aliyowahi kusema.',
  'Tumia TAKWIMU HALISI na PICKS LIVE zilizotolewa hapa chini — usibuni odds wala matokeo yasiyopo.',
  'Mtumiaji akiuliza kuhusu Altraware Technology, Mwijay, au kutengenezewa website/app/AI, mjibu kwa ufasaha na mwambie anaweza kubonyeza kitufe cha WhatsApp au Website chini ya ujumbe huu.',
  'Kila unapopendekeza dau, sisitiza nidhamu ya mtaji (STRONG 2-3u, MODERATE 1-1.5u).'
].filter(Boolean).join('\n');

const msgs = [{ role: 'system', content: SYS + '\n\n' + userMemoryCtx + '\n\n' + ALTRAWARE_PROFILE + '\n\n' + picksContext + (matchCtx ? ('\n\nMECHI INAYOANGALIWA: ' + matchCtx) : '') }];
for (const h of history.slice(0, -1)) {
  if (h && h.content && (h.role === 'user' || h.role === 'assistant')) {
    msgs.push({ role: h.role, content: String(h.content).slice(0, 600) });
  }
}
msgs.push({ role: 'user', content: question });

const cleanReply = t => String(t || '')
  .replace(/<think>[\s\S]*?<\/think>/gi, '')
  .replace(/\*\*(.*?)\*\*/g, '$1')
  .replace(/[*\x60]/g, '')
  .trim();

const keysOf = envName => String($env[envName] || '').split(',').map(s => s.trim()).filter(Boolean);
const groqKeys = keysOf('GROQ_KEYS');
const gemKeys = keysOf('GEMINI_KEYS');
const orKeys = keysOf('OPENROUTER_KEYS');

const metaOut = {
  tier: userTier,
  plan: userPlan,
  livePicksCount: published.length,
  settledCount: settled.length,
  rateLimit: rateLimitObj,
  actions: finalActions,
  memoryPayload
};

for (const mdl of ['openai/gpt-oss-120b', 'llama-3.3-70b-versatile']) {
  for (let i = 0; i < Math.min(groqKeys.length, 3); i++) {
    try {
      const payload = { model: mdl, messages: msgs, temperature: 0.35 };
      if (/gpt-oss/.test(mdl)) { payload.max_completion_tokens = 750; payload.reasoning_effort = 'low'; }
      else { payload.max_tokens = 750; }
      const r = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.groq.com/openai/v1/chat/completions',
        headers: { Authorization: 'Bearer ' + groqKeys[i], 'Content-Type': 'application/json' },
        body: payload,
        json: true,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
        timeout: 18000
      });
      const txt = cleanReply(r.body?.choices?.[0]?.message?.content);
      if (r.statusCode >= 200 && r.statusCode < 300 && txt.length > 15) {
        return [{ json: { reply: txt, provider: 'groq', model: mdl, ...metaOut } }];
      }
    } catch (e) {}
  }
}

for (let i = 0; i < Math.min(gemKeys.length, 3); i++) {
  try {
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent',
      headers: { 'x-goog-api-key': gemKeys[i], 'Content-Type': 'application/json' },
      body: {
        system_instruction: { parts: [{ text: msgs[0].content }] },
        contents: [{ role: 'user', parts: [{ text: question }] }],
        generationConfig: { temperature: 0.35, maxOutputTokens: 750, thinkingConfig: { thinkingBudget: 0 } }
      },
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 20000
    });
    const txt = cleanReply(r.body?.candidates?.[0]?.content?.parts?.map(p => p.text).join(''));
    if (r.statusCode >= 200 && r.statusCode < 300 && txt.length > 15) {
      return [{ json: { reply: txt, provider: 'gemini', model: 'gemini-2.5-flash', ...metaOut } }];
    }
  } catch (e) {}
}

for (let i = 0; i < Math.min(orKeys.length, 2); i++) {
  try {
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://openrouter.ai/api/v1/chat/completions',
      headers: { Authorization: 'Bearer ' + orKeys[i], 'Content-Type': 'application/json', 'HTTP-Referer': 'https://mwijay.duckdns.org' },
      body: { model: 'nvidia/nemotron-nano-9b-v2:free', messages: msgs, max_tokens: 750, temperature: 0.35 },
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 18000
    });
    const txt = cleanReply(r.body?.choices?.[0]?.message?.content);
    if (r.statusCode >= 200 && r.statusCode < 300 && txt.length > 15) {
      return [{ json: { reply: txt, provider: 'openrouter', model: 'nemotron-nano-9b', ...metaOut } }];
    }
  } catch (e) {}
}

return [{ json: { reply: 'Noellyne AI iko busy kwa sekunde chache. Angalia tab ya Picks au jaribu tena sasa hivi!', provider: 'fallback', model: 'none', ...metaOut } }];

// =============================================================
// Step 1: Verify Supabase JWT + extract hardware fingerprint & user profile
// =============================================================
const wh = $('App Chat Webhook').first().json || {};
const headers = wh.headers || {};
const body = wh.body && typeof wh.body === 'object' ? wh.body : wh;
const question = String(body.message || body.text || '').trim();
const history = Array.isArray(body.history) ? body.history.slice(-10) : [];
const matchCtx = body.matchContext ? JSON.stringify(body.matchContext).slice(0, 650) : '';
const rawProfile = body.userProfile && typeof body.userProfile === 'object' ? body.userProfile : {};
const profileName = String(rawProfile.name || '').trim().slice(0, 60);
const profilePinned = Array.isArray(rawProfile.pinnedTeams)
  ? rawProfile.pinnedTeams.map(t => String(t || '').trim()).filter(Boolean).slice(0, 10)
  : [];

const VIP_EMAILS = new Set([
  'davidbyanmwijage@gmail.com',
  'mwijaydavie@gmail.com',
  'faidahq.tz@gmail.com',
  'altrawaretechnology@gmail.com'
]);

const authHdr = String(headers.authorization || headers.Authorization || '').trim();
const bearer = /^Bearer\s+(.+)$/i.test(authHdr) ? authHdr.replace(/^Bearer\s+/i, '').trim() : '';

let verifiedEmail = '';
let verifiedUserId = '';
let isHardcodedVip = false;

if (bearer && bearer.length > 30) {
  try {
    const uRes = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://tahigoqhuyxedhmeqhnp.supabase.co/auth/v1/user',
      headers: {
        apikey: 'sb_publishable_o2i64llO0OwnaUMD5NUEAQ_ARb4R7T5',
        Authorization: 'Bearer ' + bearer
      },
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 5000
    });
    if (uRes.statusCode === 200 && uRes.body && uRes.body.email) {
      verifiedEmail = String(uRes.body.email).toLowerCase().trim();
      verifiedUserId = String(uRes.body.id || '').trim();
      isHardcodedVip = VIP_EMAILS.has(verifiedEmail);
    }
  } catch (e) {}
}

const cleanId = v => String(v || '').trim().replace(/[^a-zA-Z0-9._:-]/g, '').slice(0, 64);
const hwId = cleanId(body.hwId || headers['x-device-hardware-id'] || headers['X-Device-Hardware-Id']);
const deviceId = cleanId(body.deviceId || headers['x-device-id'] || headers['X-Device-Id'] || body.chatId);
const clientIp = String(headers['cf-connecting-ip'] || headers['x-forwarded-for'] || headers['x-real-ip'] || 'unknown').split(',')[0].trim();
const usageDate = new Date().toLocaleDateString('en-CA', { timeZone: 'Africa/Dar_es_Salaam' });

const qLow = question.toLowerCase();
let stakeTzs = null;
const kMatch = qLow.match(/(\d+(?:\.\d+)?)\s*k\b/);
if (kMatch) {
  const v = Math.round(parseFloat(kMatch[1]) * 1000);
  if (v >= 500 && v <= 50000000) stakeTzs = v;
} else {
  const nums = qLow.match(/\b\d{1,3}(?:,\d{3})+\b|\b\d{4,8}\b/g) || [];
  for (const s of nums) {
    const v = parseInt(s.replace(/,/g, ''), 10);
    if (v >= 500 && v <= 50000000) { stakeTzs = v; break; }
  }
}
const wantsSlip = Boolean(
  (stakeTzs !== null && /(nina|mtaji|gawa|slip|betpawa|weka|tzs|shilingi|tsh|bankroll|leo|mkeka)/i.test(qLow)) ||
  /^(gawa mtaji|betpawa slip|slip)$/i.test(qLow)
);

return [{
  json: {
    question,
    history,
    matchCtx,
    profileName,
    profilePinned,
    verifiedEmail,
    verifiedUserId,
    isHardcodedVip,
    hwId,
    deviceId,
    clientIp,
    usageDate,
    stakeTzs,
    wantsSlip,
    skipQuota: !question || wantsSlip
  }
}];

const id = $('Resolve Identity & Intent').first().json;
const entRaw = $input.first().json || {};
const ent = Array.isArray(entRaw) ? (entRaw[0] || {}) : entRaw;

let plan = id.verifiedUserId ? 'free' : 'guest';
let effectiveTier = id.verifiedUserId ? 'member' : 'guest';
let dailyLimit = id.verifiedUserId ? 10 : 3;

const notExpired = !ent.expires_at || (Date.parse(ent.expires_at) > Date.now());
if (id.isHardcodedVip || (ent.plan === 'vip_owner' && notExpired)) {
  plan = 'vip_owner';
  effectiveTier = 'vip';
  dailyLimit = -1;
} else if (ent.plan === 'pro' && notExpired) {
  plan = 'pro';
  effectiveTier = 'pro';
  const lim = Number(ent.daily_limit);
  dailyLimit = Number.isFinite(lim) ? lim : 100;
}

const keys = [];
if (id.hwId) keys.push('hw:' + id.hwId);
if (id.verifiedUserId) keys.push('uid:' + id.verifiedUserId);
if (!keys.length && id.deviceId && id.deviceId !== 'app' && id.deviceId !== 'nly-ephemeral') {
  keys.push('dev:' + id.deviceId);
}
if (!keys.length) keys.push('ip:' + id.clientIp);

// Persistent memory key prefers verified user account, then hardware fingerprint
const memoryKey = id.verifiedUserId
  ? ('uid:' + id.verifiedUserId)
  : (id.hwId ? ('hw:' + id.hwId) : (id.deviceId ? ('dev:' + id.deviceId) : ''));

return [{
  json: {
    plan,
    effectiveTier,
    dailyLimit,
    memoryKey,
    rpcPayload: {
      p_keys: keys,
      p_date: id.usageDate,
      p_limit: id.skipQuota ? -1 : dailyLimit,
      p_tier: effectiveTier,
      p_ip: id.clientIp
    }
  }
}];

const d = $input.first().json || {};
if (!d.memoryPayload || !d.memoryPayload.subject_key) return [];
return [{ json: { memoryPayload: d.memoryPayload } }];
